// Problem 12: Find triples (a,b,c) digits, a≠0, abc/cba = 2 - c/a
// Equation: a(100a+10b+c) = (2a-c)(100c+10b+a)
// Simplifies to: 10b(a-c) = 98a^2 - 199ac + 100c^2
// b = (98a^2 - 199ac + 100c^2) / (10(a-c))

let count12 = 0;
let solutions12 = [];
for (let a = 1; a <= 9; a++) {
  for (let c = 0; c <= 9; c++) {
    if (a === c) continue; // a≠c (shown above)
    let num = 98*a*a - 199*a*c + 100*c*c;
    let den = 10*(a-c);
    if (num % den === 0) {
      let b = num / den;
      if (b >= 0 && b <= 9 && Number.isInteger(b)) {
        // Also check cba is valid (c≠0 for 3-digit, but problem says cba is 3-digit integer)
        // c could be 0? Then cba = 0ba which isn't 3-digit. Let's check c≠0
        if (c !== 0) {
          // verify: abc/cba = 2 - c/a
          let abc_val = 100*a + 10*b + c;
          let cba_val = 100*c + 10*b + a;
          let lhs = abc_val / cba_val;
          let rhs = 2 - c/a;
          if (Math.abs(lhs - rhs) < 1e-9) {
            solutions12.push([a,b,c]);
            count12++;
          }
        }
      }
    }
  }
}
// Also check if c=0 allowed (cba would be 0ba, not 3-digit, so exclude)
console.log("Problem 12 count:", count12);
console.log("Solutions:", JSON.stringify(solutions12));

