from fractions import Fraction

def binom_prob(n, k):
    from math import comb
    return Fraction(comb(n, k), 2**n)

# After 2 flips: cases where E2 > A2
# (e2, a2) with e2 > a2
cases_2 = []
for e2 in range(3):
    for a2 in range(3):
        if e2 > a2:
            p = binom_prob(2, e2) * binom_prob(2, a2)
            cases_2.append((e2, a2, p))

p_e2_gt_a2 = sum(c[2] for c in cases_2)
print("P(E2>A2) =", p_e2_gt_a2)

# For each case, compute P(E2+X > A2+Y) where X,Y ~ Bin(3,1/2)
# = P(X - Y > a2 - e2) = P(X - Y > d) where d = a2 - e2 < 0
total = Fraction(0)
for (e2, a2, p) in cases_2:
    d = a2 - e2  # negative
    # P(X > Y + d) = P(X - Y > d)
    prob_win = Fraction(0)
    for x in range(4):
        for y in range(4):
            if x > y + d:
                prob_win += binom_prob(3, x) * binom_prob(3, y)
    total += p * prob_win

