def solve_p12():
    solutions = []
    for a in range(1, 10):
        for c in range(1, 10):
            # 5b(c-3a) = (49a - 50c)(c-a)
            # if c - 3a != 0:
            # b = (49a - 50c)(c-a) / (5(c-3a))
            numerator = (49*a - 50*c)*(c-a)
            denominator = 5*(c - 3*a)
            if denominator == 0:
                if numerator == 0:
                    for b in range(10):
                        solutions.append((a, b, c))
            else:
                if numerator % denominator == 0:
                    b = numerator // denominator
                    if 0 <= b <= 9:
                        solutions.append((a, b, c))
    return solutions
